import os, base64, hashlib, csv, glob
root='.'
for di in sorted(glob.glob('*.dist-info')):
    rec=os.path.join(di,'RECORD')
    if not os.path.exists(rec): print(di,'NO RECORD'); continue
    listed=set()
    problems=[]
    for row in csv.reader(open(rec)):
        if not row: continue
        path=row[0]; h=row[1] if len(row)>1 else ''
        listed.add(os.path.normpath(path))
        if not h: continue
        if not os.path.exists(path):
            problems.append(('MISSING',path)); continue
        algo,val=h.split('=',1)
        d=hashlib.new(algo, open(path,'rb').read()).digest()
        got=base64.urlsafe_b64encode(d).rstrip(b'=').decode()
        if got!=val: problems.append(('HASH-MISMATCH',path))
    # find files on disk belonging to top_level not in RECORD
    tl=os.path.join(di,'top_level.txt')
    extras=[]
    if os.path.exists(tl):
        for pkg in open(tl).read().split():
            for dirpath,dirs,files in os.walk(pkg):
                for f in files:
                    p=os.path.normpath(os.path.join(dirpath,f))
                    if p not in listed: extras.append(p)
            if os.path.isfile(pkg+'.py') and os.path.normpath(pkg+'.py') not in listed:
                extras.append(pkg+'.py')
    for e in extras: problems.append(('NOT-IN-RECORD',e))
    if problems:
        print('==',di)
        for k,v in problems: print('   ',k,v)
EOF

